pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PoCGame c;
    bool public failed;

    function setUp() public {
        vm.prank(address(this), address(this));
        c = new PoCGame(address(this), 0);
    }

    function _test(uint256 newLimit) internal {
        vm.assume(newLimit > 0);
        uint256 oldLimit;
        try c.currentBetLimit() returns (uint256 __r) { oldLimit = __r; } catch { return; }
        try c.AdjustBetAmounts(newLimit) {} catch { return; }
        uint256 newLimitObs;
        try c.currentBetLimit() returns (uint256 __r) { newLimitObs = __r; } catch { return; }
        assertTrue(newLimitObs == newLimit);
    }

    function testFuzz_test(uint256 newLimit) public {
        _test(newLimit);
    }

    receive() external payable {}
}
